package replica;

import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.graphics.Color;import android.view.*;import android.view.accessibility.AccessibilityNodeInfo;import android.widget.*;import android.text.*;import java.util.*;

/** Settings-style editor: 3x4 selected slots, available controls and launcher apps. */
public final class ToolsSettingsActivity extends Activity {
 private ArrayList<ToolsConfig.Item> selected;private String original;private LinearLayout grid,candidates;private TextView count,save;private ScrollView scroll;private boolean saving;private final ArrayList<AlertDialog> dialogs=new ArrayList<>();private final java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();
 private FrameLayout pageHost;private ColorSettingsScaffold editor;private final ColorPageMotion pageMotion=new ColorPageMotion();private ColorAppPickerPage appPicker;
 private ColorOsTheme.Subscription themeSubscription;private int bg,card,text,muted,tileNameHeight,tileHeight;private int dp(float n){return PanelStyle.dp(this,n);}
 private TextView label(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setTypeface(ColorOsTheme.typeface(this,400));t.setIncludeFontPadding(false);t.setGravity(Gravity.CENTER_VERTICAL);return t;}
 private TextView button(String s,Runnable action){TextView t=label(s,15,ColorOsTheme.accent(this));t.setTypeface(ColorOsTheme.typeface(this,500));t.setGravity(Gravity.CENTER);t.setSingleLine(true);t.setPadding(dp(12),0,dp(12),0);t.setMinHeight(dp(48));t.setBackground(ColorDialogBuilder.touchBackground(this,Color.TRANSPARENT,14));t.setContentDescription(s);t.setOnClickListener(v->action.run());return t;}
 private void show(AlertDialog dialog){if(isFinishing()||isDestroyed())return;dialogs.add(dialog);dialog.setOnDismissListener(d->dialogs.remove(dialog));dialog.show();}
 private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
 private String encoded(){try{return ToolsConfig.encode(selected);}catch(Exception e){throw new IllegalStateException(e);}}
 private boolean dirty(){return !encoded().equals(original);}
 @Override public void onCreate(Bundle state){boolean dark=PanelStyle.dark(this);setTheme(getResources().getIdentifier(dark?"AppThemeDark":"AppTheme","style",getPackageName()));super.onCreate(state);
  if(Build.VERSION.SDK_INT>=34){overrideActivityTransition(OVERRIDE_TRANSITION_OPEN,animation("open_in"),animation("open_out"));overrideActivityTransition(OVERRIDE_TRANSITION_CLOSE,animation("close_in"),animation("close_out"));}else overridePendingTransition(animation("open_in"),animation("open_out"));
  selected=ToolsConfig.load(this);original=encoded();if(state!=null)try{selected=ToolsConfig.parse(state.getString("draft"));original=state.getString("original",original);}catch(Exception ignored){}
  pageHost=new FrameLayout(this);setContentView(pageHost);buildPage();if(state!=null){int scrollY=state.getInt("scroll_y",0);scroll.post(()->scroll.scrollTo(0,scrollY));if(state.getBoolean("choosing_app",false))openAppPage(state.getString("app_query",""),state.getInt("app_first",state.getInt("app_scroll",0)/Math.max(1,dp(72))),0);}
  themeSubscription=ColorOsTheme.observe(this,()->{if(isFinishing()||isDestroyed())return;int y=scroll.getScrollY();buildPage();scroll.post(()->scroll.scrollTo(0,y));});
 }
 private int animation(String name){return getResources().getIdentifier("color_settings_"+name,"anim",getPackageName());}
 @Override public void finish(){super.finish();if(Build.VERSION.SDK_INT<34)overridePendingTransition(animation("close_in"),animation("close_out"));}
 private void buildPage(){
  boolean picking=appPicker!=null;String query=picking?appPicker.query():"";int appScroll=picking?appPicker.firstVisibleIndex():0;if(appPicker!=null){appPicker.close();appPicker=null;}
  bg=ColorOsTheme.background(this);card=ColorOsTheme.card(this);text=ColorOsTheme.text(this);muted=ColorOsTheme.secondary(this);
  tileNameHeight=Math.max(dp(32),label("",11,text).getLineHeight()*2);tileHeight=Math.max(dp(88),dp(7)+dp(44)+tileNameHeight+dp(5));
  getWindow().setDecorFitsSystemWindows(false);ColorOsTheme.install(this);ColorSettingsScaffold scaffold=new ColorSettingsScaffold(this,"快速工具",false,this::onBackPressed);editor=scaffold;pageMotion.show(pageHost,scaffold.root,0);save=button("保存",this::save);save.setMinimumWidth(Math.max(dp(64),(int)Math.ceil(save.getPaint().measureText(save.getText().toString()))+save.getPaddingLeft()+save.getPaddingRight()+dp(2)));scaffold.setTrailing(save);scroll=scaffold.scroll;LinearLayout content=scaffold.content;
  TextView hint=label("长按拖动排序，点击已添加的按钮可移除。\n最多添加 12 个，保存后应用到面板底部三排。",14,muted);hint.setPadding(dp(4),dp(4),dp(4),dp(16));content.addView(hint);
  LinearLayout heading=new LinearLayout(this);count=label("",16,text);heading.addView(count,new LinearLayout.LayoutParams(0,dp(48),1));heading.addView(button("恢复默认",()->{if(!saving){selected=ToolsConfig.defaults();render();}}));content.addView(heading);
  grid=new LinearLayout(this);grid.setOrientation(LinearLayout.VERTICAL);grid.setPadding(dp(6),dp(8),dp(6),dp(8));grid.setBackground(PanelStyle.shape(this,card,20));LinearLayout.LayoutParams gridParams=new LinearLayout.LayoutParams(-1,-2);gridParams.bottomMargin=dp(14);content.addView(grid,gridParams);
  TextView section=label("可添加功能",14,muted);section.setTypeface(ColorOsTheme.typeface(this,500));section.setPadding(dp(6),dp(10),0,dp(8));content.addView(section);
  candidates=new LinearLayout(this);candidates.setOrientation(LinearLayout.VERTICAL);candidates.setPadding(dp(6),dp(8),dp(6),dp(8));candidates.setBackground(PanelStyle.shape(this,card,20));content.addView(candidates);
  TextView apps=button("添加应用快捷入口",this::chooseApp);LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,dp(56));ap.topMargin=dp(16);apps.setBackground(ColorDialogBuilder.touchBackground(this,card,20));content.addView(apps,ap);render();if(picking)openAppPage(query,appScroll,0);
 }
 private boolean contains(String key){return index(key)>=0;}private int index(String key){for(int i=0;i<selected.size();i++)if(selected.get(i).key.equals(key))return i;return -1;}
 private void add(ToolsConfig.Item item){if(saving)return;if(contains(item.key)){toast("已添加此按钮");return;}if(selected.size()>=ToolsConfig.LIMIT){toast("已满 12 个，请先移除一个按钮");return;}selected.add(item);render();}
 private void remove(String key){if(saving)return;int at=index(key);if(at>=0){selected.remove(at);render();}}
 private void move(String key,int target){if(saving)return;int from=index(key);if(from<0||target<0||target>=selected.size()||from==target)return;ToolsConfig.Item item=selected.remove(from);selected.add(target,item);}
 private void render(){count.setText("已添加 "+selected.size()+" / 12");save.setEnabled(!saving);grid.removeAllViews();candidates.removeAllViews();
  for(int row=0;row<3;row++){LinearLayout line=new LinearLayout(this);grid.addView(line,new LinearLayout.LayoutParams(-1,tileHeight));for(int col=0;col<4;col++){int at=row*4+col;View v;if(at<selected.size())v=tile(selected.get(at),true,at);else{FrameLayout empty=new FrameLayout(this);ImageView plus=new ImageView(this);plus.setImageDrawable(SystemIcons.raw(this,"com.android.settings:ic_add_24dp"));plus.setColorFilter(muted);plus.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);empty.addView(plus,new FrameLayout.LayoutParams(dp(28),dp(28),Gravity.CENTER));empty.setBackground(ColorDialogBuilder.touchBackground(this,Color.TRANSPARENT,14));empty.setContentDescription("空位置 "+(at+1));empty.setOnClickListener(w->scroll.smoothScrollTo(0,candidates.getTop()));v=empty;}line.addView(v,new LinearLayout.LayoutParams(0,-1,1));}}
  ArrayList<ToolsConfig.Item> available=new ArrayList<>();for(int i=0;i<ToolsConfig.TITLES.length;i++)if(ToolsConfig.available(this,i)&&!contains(Integer.toString(i)))available.add(ToolsConfig.builtin(i));
  for(int row=0;row<(available.size()+3)/4;row++){LinearLayout line=new LinearLayout(this);candidates.addView(line,new LinearLayout.LayoutParams(-1,tileHeight));for(int col=0;col<4;col++){int at=row*4+col;line.addView(at<available.size()?tile(available.get(at),false,at):new View(this),new LinearLayout.LayoutParams(0,-1,1));}}
 }
 private View tile(ToolsConfig.Item item,boolean chosen,int position){android.widget.FrameLayout cell=new android.widget.FrameLayout(this);cell.setBackground(ColorDialogBuilder.touchBackground(this,Color.TRANSPARENT,14));cell.setContentDescription((chosen?"已添加 ":"添加 ")+item.label+(chosen?"，位置 "+(position+1):""));
  LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setGravity(Gravity.CENTER_HORIZONTAL);body.setPadding(0,dp(7),0,0);cell.addView(body,new android.widget.FrameLayout.LayoutParams(-1,-1));ImageView icon=new ImageView(this);icon.setImageDrawable(ToolsConfig.icon(this,item));icon.setScaleType(ImageView.ScaleType.FIT_CENTER);icon.setBackground(PanelStyle.shape(this,ColorOsTheme.dark(this)?0xff303236:0xfff0f1f3,24));icon.setPadding(dp(item.component()==null?4:8),dp(item.component()==null?4:8),dp(item.component()==null?4:8),dp(item.component()==null?4:8));if(item.component()==null)icon.setColorFilter(chosen?ColorOsTheme.text(this):muted);body.addView(icon,new LinearLayout.LayoutParams(dp(44),dp(44)));
  TextView name=label(item.label,11,text);name.setGravity(Gravity.CENTER);name.setMaxLines(2);name.setEllipsize(TextUtils.TruncateAt.END);body.addView(name,new LinearLayout.LayoutParams(-1,tileNameHeight));
  ImageView badge=new ImageView(this);badge.setImageDrawable(SystemIcons.raw(this,"com.android.settings:"+(chosen?"ic_remove_24dp":"ic_add_24dp")));badge.setColorFilter(chosen?ColorOsTheme.error(this):ColorOsTheme.accent(this));badge.setScaleType(ImageView.ScaleType.FIT_CENTER);badge.setPadding(dp(3),dp(3),dp(3),dp(3));badge.setBackground(PanelStyle.shape(this,card,9));android.widget.FrameLayout.LayoutParams bp=new android.widget.FrameLayout.LayoutParams(dp(18),dp(18),Gravity.TOP|Gravity.RIGHT);bp.topMargin=dp(3);bp.rightMargin=dp(5);cell.addView(badge,bp);
  body.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO_HIDE_DESCENDANTS);badge.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);cell.setFocusable(true);cell.setOnClickListener(v->{if(chosen)remove(item.key);else add(item);});
  if(chosen){cell.setOnLongClickListener(v->{boolean started=v.startDragAndDrop(ClipData.newPlainText("tool",item.key),new View.DragShadowBuilder(v),item.key,0);if(started)v.setAlpha(.35f);return started;});cell.setOnDragListener((v,e)->{if(!(e.getLocalState() instanceof String))return false;switch(e.getAction()){case DragEvent.ACTION_DRAG_STARTED:return true;case DragEvent.ACTION_DRAG_ENTERED:v.setBackground(PanelStyle.shape(this,(ColorOsTheme.accent(this)&0xffffff)|0x20000000,14));return true;case DragEvent.ACTION_DRAG_EXITED:v.setBackground(ColorDialogBuilder.touchBackground(this,Color.TRANSPARENT,14));return true;case DragEvent.ACTION_DROP:move((String)e.getLocalState(),position);grid.post(this::render);return true;case DragEvent.ACTION_DRAG_ENDED:v.setAlpha(1);v.setBackground(ColorDialogBuilder.touchBackground(this,Color.TRANSPARENT,14));return true;default:return true;}});
   cell.setAccessibilityDelegate(new View.AccessibilityDelegate(){public void onInitializeAccessibilityNodeInfo(View v,AccessibilityNodeInfo info){super.onInitializeAccessibilityNodeInfo(v,info);if(position>0)info.addAction(new AccessibilityNodeInfo.AccessibilityAction(0x01010001,"向前移动"));if(position<selected.size()-1)info.addAction(new AccessibilityNodeInfo.AccessibilityAction(0x01010002,"向后移动"));}public boolean performAccessibilityAction(View v,int action,Bundle b){if(action==0x01010001||action==0x01010002){move(item.key,index(item.key)+(action==0x01010001?-1:1));render();return true;}return super.performAccessibilityAction(v,action,b);}});
  }return cell;
 }
 private void chooseApp(){if(saving)return;if(selected.size()>=ToolsConfig.LIMIT){toast("已满 12 个，请先移除一个按钮");return;}openAppPage("",0,1);}
 private void openAppPage(String query,int y,int direction){
  if(appPicker!=null)appPicker.close();ArrayList<String> excluded=new ArrayList<>();for(ToolsConfig.Item item:selected)excluded.add(item.key);
  appPicker=new ColorAppPickerPage(this,worker,excluded,query,y,this::onBackPressed,item->{if(saving||appPicker==null)return;add(item);closeAppPage();});
  getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);pageMotion.show(pageHost,appPicker.scaffold.root,direction);
 }
 private void closeAppPage(){ColorAppPickerPage picker=appPicker;if(picker==null)return;appPicker=null;picker.hideKeyboard();picker.close();pageMotion.show(pageHost,editor.root,-1);}
 private void save(){if(saving)return;saving=true;save.setEnabled(false);ArrayList<ToolsConfig.Item> snapshot=new ArrayList<>(selected);worker.execute(()->{try{ToolsConfig.save(this,snapshot);runOnUiThread(()->{if(isDestroyed())return;original=encoded();saving=false;toast("已保存快速工具布局");finish();});}catch(Exception e){runOnUiThread(()->{if(isDestroyed())return;saving=false;save.setEnabled(true);toast("保存失败，请重试");});}});}
 @Override public void onBackPressed(){if(appPicker!=null){closeAppPage();return;}if(saving)return;if(dirty())show(new ColorDialogBuilder(this).setSettingsConfirmation().setTitle("放弃修改？").setMessage("尚未保存的按钮布局将不会应用。").setNegativeButton("继续编辑",null).setPositiveDestructive("放弃",(d,w)->finish()).create());else super.onBackPressed();}
 @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putString("draft",encoded());state.putString("original",original);if(scroll!=null)state.putInt("scroll_y",scroll.getScrollY());if(appPicker!=null){state.putBoolean("choosing_app",true);state.putString("app_query",appPicker.query());state.putInt("app_first",appPicker.firstVisibleIndex());}}
 @Override protected void onDestroy(){if(appPicker!=null)appPicker.close();pageMotion.clear();if(themeSubscription!=null)themeSubscription.close();for(AlertDialog dialog:new ArrayList<>(dialogs))ColorDialogBuilder.dismissImmediately(dialog);dialogs.clear();worker.shutdownNow();super.onDestroy();}
}
